func (r *QueryResolver) DeskBoardCard(ctx context.Context, threadID string, artifactID string) (*gqlmodel.DeskBoardCard, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceAssistant, permission.OpRead)
	if err != nil {
		return nil, err
	}
	thread, err := pulid.Parse(threadID)
	if err != nil {
		return nil, err
	}
	artifact, err := pulid.Parse(artifactID)
	if err != nil {
		return nil, err
	}

	card, err := r.BoardCards.Card(ctx, &agentports.BoardCardRequest{
		Thread: agentports.GetThreadRequest{
			ID:         thread,
			UserID:     authCtx.UserID,
			TenantInfo: base.TenantInfo(authCtx),
		},
		ArtifactID: artifact,
		Actor:      actorutil.FromAuthContext(authCtx),
	})
	if err != nil {
		return nil, err
	}

	return boardCardToModel(card), nil
}
